//! One additional front-seam comparison bit from a classical source operand.
//! The original inherited passes run first. Their low-fold edits remain intact.
//! A complete actual region and its source-derived interfaces are mandatory.
use crate::circuit::{Op,OperationType as K,QubitId,BitId,RegisterId,QubitOrBit,analyze_ops};
use std::collections::BTreeSet;
const NONE:u64=u64::MAX;
const DATA:&[u8]=include_bytes!("front_seam.bin");
fn decode(bytes:&[u8])->Vec<Op>{assert_eq!(bytes.len()%56,0);bytes.chunks_exact(56).map(|b|{let u=|i|u64::from_le_bytes(b[i..i+8].try_into().unwrap());let kind=match u(0){0=>K::Neg,1=>K::Register,2=>K::AppendToRegister,3=>K::BitInvert,4=>K::BitStore0,5=>K::BitStore1,6=>K::X,7=>K::Z,8=>K::CX,9=>K::CZ,10=>K::Swap,11=>K::R,12=>K::Hmr,13=>K::CCX,14=>K::CCZ,15=>K::PushCondition,16=>K::PopCondition,17=>K::DebugPrint,_=>panic!("front seam operation")};let o=Op{kind,q_control2:QubitId(u(8)),q_control1:QubitId(u(16)),q_target:QubitId(u(24)),c_target:BitId(u(32)),c_condition:BitId(u(40)),r_target:RegisterId(u(48))};o.validate();o}).collect()}
fn spec()->(Vec<Op>,Vec<Op>){assert_eq!(&DATA[..8],b"FRONTSE1");let n=u32::from_le_bytes(DATA[8..12].try_into().unwrap())as usize;let m=u32::from_le_bytes(DATA[12..16].try_into().unwrap())as usize;assert_eq!(m,n+4);assert_eq!(DATA.len(),16+56*(n+m));(decode(&DATA[16..16+56*n]),decode(&DATA[16+56*n..]))}
fn quantum(ops:&[Op])->BTreeSet<u64>{ops.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|q|*q!=NONE).collect()}
fn depth(d:usize,o:&Op)->usize{match o.kind{K::PushCondition=>d+1,K::PopCondition=>d.checked_sub(1).expect("front seam scope underflow"),_=>d}}
fn quantum_write(o:&Op,q:u64)->bool{matches!(o.kind,K::X|K::CX|K::CCX|K::R|K::Hmr)&&o.q_target.0==q||o.kind==K::Swap&&(o.q_target.0==q||o.q_control1.0==q)}
fn and(a:i8,b:i8)->i8{if a==0||b==0{0}else if a==1&&b==1{1}else{-1}}
fn xor(a:i8,b:i8)->i8{if a<0||b<0{-1}else{a^b}}
fn store(old:i8,c:i8,value:i8)->i8{if c==0{old}else if c==1||old==value{value}else{-1}}
// Conservative propagation: all declared input bits arbitrary, all auxiliary
// wires zero, every MR outcome arbitrary, and Push stores a value snapshot.
fn prefix_zeros(ops:&[Op],at:usize,nq:usize,nb:usize,regs:&[Vec<QubitOrBit>])->Vec<i8>{let mut q=vec![0;nq];let mut b=vec![0;nb];for r in regs{for w in r{match w{QubitOrBit::Qubit(id)=>q[id.0 as usize]=-1,QubitOrBit::Bit(id)=>b[id.0 as usize]=-1}}}let mut base=1;let mut stack=Vec::new();for o in &ops[..at]{let c=if o.c_condition.0==NONE{base}else{and(base,b[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let bt=o.c_target.0 as usize;match o.kind{K::X=>q[t]=xor(q[t],c),K::CX=>q[t]=xor(q[t],and(c,q[o.q_control1.0 as usize])),K::CCX=>q[t]=xor(q[t],and(c,and(q[o.q_control1.0 as usize],q[o.q_control2.0 as usize]))),K::Swap=>{let a=o.q_control1.0 as usize;let x=q[t];let y=q[a];q[t]=store(x,c,y);q[a]=store(y,c,x);},K::R|K::Hmr=>{q[t]=store(q[t],c,0);if o.kind==K::Hmr{b[bt]=store(b[bt],c,-1);}},K::BitInvert=>b[bt]=xor(b[bt],c),K::BitStore0=>b[bt]=store(b[bt],c,0),K::BitStore1=>b[bt]=store(b[bt],c,1),K::PushCondition=>{stack.push(base);base=c;},K::PopCondition=>base=stack.pop().unwrap(),_=>{}}}assert!(stack.is_empty()&&base==1,"front seam prefix scope");q}
fn static_contract(old:&[Op],new:&[Op]){assert_eq!(quantum(old),quantum(new),"front seam physical capacity/interface");let skeleton=|s:&[Op]|s.iter().filter(|o|matches!(o.kind,K::R|K::Hmr|K::BitInvert|K::BitStore0|K::BitStore1|K::PushCondition|K::PopCondition)).copied().collect::<Vec<_>>();assert_eq!(skeleton(old),skeleton(new),"front seam measurement/classical/snapshot sequence");let tof=|s:&[Op]|s.iter().filter(|o|matches!(o.kind,K::CCX|K::CCZ)).map(|o|(o.kind,o.c_condition)).collect::<Vec<_>>();assert_eq!(tof(old),tof(new),"front seam executed Toffoli sequence");let mut d=0;for o in old{d=depth(d,o);}assert_eq!(d,0);for o in new{d=depth(d,o);}assert_eq!(d,0);}
pub fn run(ops:Vec<Op>)->Vec<Op>{let(old,new)=spec();static_contract(&old,&new);let matches=ops.windows(old.len()).enumerate().filter(|(_,s)|*s==old.as_slice()).map(|(i,_)|i).collect::<Vec<_>>();assert_eq!(matches.len(),1,"front seam complete actual region missing/changed/ambiguous");let at=matches[0];let(nq,nb,_,regs)=analyze_ops(ops.iter());assert_eq!(regs.len(),4);assert!(regs.iter().all(|r|r.len()==256));assert_eq!(regs[0][235],QubitOrBit::Qubit(QubitId(235)));assert_eq!(regs[2][235],QubitOrBit::Bit(BitId(235)));for o in &ops[..at]{assert!(!(0..256).any(|q|quantum_write(o,q)),"front seam input x changed before exact subtraction");}assert!(ops.iter().all(|o|!(matches!(o.kind,K::Hmr|K::BitInvert|K::BitStore0|K::BitStore1)&&o.c_target.0<256)),"front seam classical ox mutated");let initial=prefix_zeros(&ops,at,nq as usize,nb as usize,&regs);let prefix_len=6128;let hmr_offset=7211;assert_eq!(old[hmr_offset].kind,K::Hmr);assert_eq!(old[hmr_offset].q_target.0,767);for q in quantum(&old[..prefix_len]){if q>=512{assert_eq!(initial[q as usize],0,"front seam subtraction scratch not proved zero");}}let mut d=0;let mut upper=[0;20];let mut ov=0;for o in &old[prefix_len..hmr_offset]{if quantum_write(o,235){panic!("front seam lower D bit changed");}for q in 236..256{if quantum_write(o,q){assert_eq!(o.kind,K::X);assert_eq!(o.c_condition.0,NONE);assert_eq!(d,0);upper[(q-236)as usize]+=1;}}if quantum_write(o,767){assert_eq!(o.kind,K::X);assert_eq!(o.c_condition.0,NONE);assert_eq!(d,0);ov+=1;}d=depth(d,o);}assert_eq!(d,0);assert_eq!(upper,[1;20]);assert_eq!(ov%2,0);eprintln!("FRONT_SEAM_CLASSICAL_BORROW at={at} bits20to21 extraT=0 extraQ=0 extraMR=0 all_tables_retained=true");let mut out=Vec::with_capacity(ops.len()+4);out.extend_from_slice(&ops[..at]);out.extend_from_slice(&new);out.extend_from_slice(&ops[at+old.len()..]);out}
#[cfg(test)]mod tests{use super::*;fn synthetic()->Vec<Op>{let(old,_)=spec();let mut ops=old;for r in 0..4{for i in 0..256{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(r);if r<2{o.q_target=QubitId(r*256+i);}else{o.c_target=BitId((r-2)*256+i);}ops.push(o);}let mut o=Op::empty();o.kind=K::Register;o.r_target=RegisterId(r);ops.push(o);}ops}
#[test]fn complete_static_interfaces(){let(a,b)=spec();static_contract(&a,&b);}
#[test]fn accepts_complete_named_source(){let s=synthetic();assert_eq!(run(s.clone()).len(),s.len()+4);}
#[test]#[should_panic]fn changed_region_rejected(){let mut s=synthetic();s[1].q_target=QubitId(2);run(s);}
#[test]#[should_panic]fn ambiguous_region_rejected(){let mut s=synthetic();let(a,_)=spec();s.extend(a);run(s);}
#[test]#[should_panic]fn changed_classical_source_rejected(){let mut s=synthetic();let mut o=Op::empty();o.kind=K::BitInvert;o.c_target=BitId(235);s.insert(0,o);run(s);}
#[test]#[should_panic]fn dirty_subtraction_scratch_rejected(){let mut s=synthetic();let mut o=Op::empty();o.kind=K::X;o.q_target=QubitId(767);s.insert(0,o);run(s);}
#[test]fn snapshot_value_survives_mutated_control(){assert_eq!(store(0,-1,0),0);assert_eq!(and(0,-1),0);assert_eq!(store(-1,1,0),0);}
}
